(function(){
const stepNames=[['模板与数据','确认模板与数据'],['表单设计','配置作业申请表单'],['流程编排','组合流程节点'],['测试与发布','检查并发布']];
buildSteps=function(active){return `<nav class="steps workflow-steps simplified-steps">${stepNames.map((step,index)=>{const n=index+1;return `<span class="step-link ${active>n?'done':active===n?'active':''}"><strong>${active>n?'✓':n} ${step[0]}</strong><small>${step[1]}</small></span>`}).join('')}</nav>`};
function top(step){const template=state.template||state.creation;return `<div class="build-top"><div class="build-brand"><span>${state.creation?.icon||template?.icon||'◈'}</span><div><b>${template?.name||'新建模板'}</b><small>　${template?.code||''}</small></div></div>${buildSteps(step)}<div class="actions"><span class="autosave-indicator">✓ 已自动保存</span><button class="ghost" id="simpleClose">关闭</button><button class="primary" id="simpleNext">下一步</button></div></div>`}
function ensure(){if(!state.template&&state.creation)state.template=state.creation;if(!state.creation&&state.template)state.creation={...state.template,workLevelIds:['ALL']};if(state.creation)state.creation.workLevelIds=['ALL']}
renderResourceStep=function(view='basic'){ensure();const template=state.template||state.creation;title.textContent=`${template.name} · 模板与数据`;subtitle.textContent='仅保留模板识别与必要数据来源';const basic=`<section class="simplified-card"><h2>模板身份</h2><p>模板适用于当前作业类型的所有等级。</p><div class="simplified-identity">${[['模板类型',TEMPLATE_TYPE_LABELS[DEFAULT_TEMPLATE_TYPE]],['模板编码',template.code],['作业类别',template.category||state.creation.category],['作业类型',template.name.replace(/模板$/,'')],['适用范围','全部作业等级'],['标准配置','当前作业类型已发布配置'],['创建人','王安全'],['状态',template.status||'草稿']].map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></section>`;const sources=[['作业票','主数据','保存作业申请的基本信息和当前状态'],['风险与安全措施','业务明细','支撑风险评估与措施确认'],['作业人员','业务明细','保存作业人员、监护人和资质快照'],['流程记录','业务明细','保存节点办理结果、意见和签名'],['附件','业务明细','保存作业文件、现场照片和签名']];const data=`<section class="simplified-card"><h2>数据来源</h2><p>原型阶段仅展示模板运行所需的核心数据，物理表、关联键和扩展对象由研发阶段实现。</p><div class="simple-source-list">${sources.map((x,i)=>`<div class="simple-source-row"><div><b>${x[0]}</b><small>${i?'关联作业票':'每张作业票一条记录'}</small></div><span>${x[2]}</span><em>${x[1]}</em></div>`).join('')}</div><div class="simple-source-note">气体检测、交底、验收等数据由对应业务控件负责，不在模板中单独配置数据表。</div></section>`;app.innerHTML=`<div class="build-shell">${top(1)}<div class="simplified-settings"><aside class="build-nav simplified-nav"><b>模板与数据</b><button class="${view==='basic'?'active':''}" data-simple-settings="basic">基础设置<span>›</span></button><button class="${view==='data'?'active':''}" data-simple-settings="data">数据来源<span>›</span></button><button class="${view==='permission'?'active':''}" data-simple-settings="permission">字段权限<span>›</span></button></aside><main>${view==='permission'?defaultPermissionView():view==='data'?data:basic}</main></div></div>`;document.querySelectorAll('[data-simple-settings]').forEach(b=>b.onclick=()=>renderResourceStep(b.dataset.simpleSettings));document.querySelector('#simpleClose').onclick=centerView;document.querySelector('#simpleNext').onclick=renderFormBuildStep;document.querySelector('#savePermissions')?.addEventListener('click',()=>toast('字段默认权限已保存'))};
openDesigner=function(id){state.template=templates.find(t=>t.id===id);state.creation={...state.template,workLevelIds:['ALL']};if(state.template?.templateMode==='new'){flowNodes=[];selectedFlowId='';if(typeof canvasControls!=='undefined'){canvasControls=[];activeControl=0}}state.mode='resource';window.scrollTo(0,0);renderResourceStep('basic')};
const formBefore=renderFormBuildStep;renderFormBuildStep=function(){ensure();formBefore();document.querySelector('#nextFlow').onclick=()=>{state.mode='flow';renderDesigner()};document.querySelector('#previousStep').onclick=()=>renderResourceStep('basic')};
const general=['开始节点','结束节点','审批节点','条件分支'];const beforeWork=['风险评估','安全措施确认','气体检测','安全交底','接收交底'];const duringWork=['气体检测','监管确认','提交验收','验收审批'];const standard=[...new Set([...beforeWork,...duringWork])];let selectedFlowId='risk';let approvalRows=[{name:'作业负责人意见',role:'作业负责人',photo:'非必填'},{name:'所在单位意见',role:'作业所在单位负责人',photo:'非必填'},{name:'安全管理部门意见',role:'安全管理人员',photo:'非必填'}];let flowNodes=[{id:'start',name:'申请作业票',type:'开始节点'},{id:'risk',name:'风险评估',type:'办理节点',business:true,baseName:'风险评估',stage:'作业前'},{id:'approval',name:'作业审批',type:'审批节点'},{id:'finish',name:'结束',type:'结束节点'}];window.resetBlankTemplateDesigner=()=>{flowNodes=[];selectedFlowId='';if(typeof canvasControls!=='undefined'){canvasControls=[];activeControl=0}};
function libGroup(title,items,stage=''){return `<div class="node-library-group"><b>${title}</b>${items.map(x=>`<button draggable="true" data-simple-library="${x}" data-simple-stage="${stage}">＋ ${x}${x==='气体检测'?` <em>${stage}</em>`:''}</button>`).join('')}</div>`}function nodeCard(n){return `<article draggable="true" class="simple-flow-node ${selectedFlowId===n.id?'selected':''}" data-simple-node="${n.id}"><b>${n.name}</b><span>${n.business?'办理节点 · '+n.stage:n.type}</span><small>拖动调整流程顺序</small></article>`}function board(){return flowNodes.length?`<div class="simple-flow-line">${flowNodes.map(nodeCard).join('')}</div>`:'<div class="simple-flow-empty">暂无流程节点，请从左侧拖入节点</div>'}
function flowProperties(){const n=flowNodes.find(x=>x.id===selectedFlowId)||flowNodes[0];if(!n)return '<div class="simple-property-empty">请选择画布节点</div>';if(n.type==='审批节点')return `<aside class="simple-node-properties approval-properties"><div class="property-title"><div><h3>作业审批</h3><p>按业务角色配置审批顺序。</p></div><button class="primary" id="addApprovalRow">＋ 新增</button></div><label>节点类型<input value="审批节点" readonly></label><div class="property-tags"><span>同意</span><span>退回</span><span>驳回</span></div><table class="approval-role-table"><thead><tr><th>审批节点</th><th>审批人</th><th>现场照片</th><th>操作</th></tr></thead><tbody>${approvalRows.map((x,i)=>`<tr><td>${x.name}</td><td>${x.role}</td><td>${x.photo}</td><td><button data-edit-approval="${i}">编辑</button><button data-delete-approval="${i}">删除</button></td></tr>`).join('')}</tbody></table></aside>`;if(!n.business)return `<aside class="simple-node-properties"><h3>${n.name}</h3><label>节点类型<input value="${n.type}" readonly></label><p>${n.type==='开始节点'?'提交作业票后进入作业前业务流程。':'流程控制节点不绑定业务页面。'}</p></aside>`;const name=n.baseName||n.name,special=name==='接收交底'?'多人独立确认，全部完成后汇聚':name==='监管确认'?'施工单位确认 → 业主单位确认（顺序待办）':name==='提交验收'?'施工单位收尾 → 业主单位收尾，完成后进入验收审批':name==='气体检测'?`${n.stage}填报；同一气体检测页面可在不同环节重复使用`:'页面校验通过后完成';return `<aside class="simple-node-properties"><h3>${n.name} · 节点属性</h3><p>底层节点类型固定为“办理节点”，绑定业务页面。</p><label>节点类型<input value="办理节点" readonly></label><label>业务环节<input value="${n.stage}" readonly></label><label>绑定页面<select><option>${name}</option></select></label><label>办理人<select><option>${name==='监管确认'?'施工单位、业主单位':'业务环节负责人'}</option><option>指定成员</option></select></label><label>单人/多人模式<select><option>${name==='接收交底'?'多人独立确认':'单人办理'}</option><option>多人顺序办理</option></select></label><label>输入输出<textarea>输入：作业票及前序结果\n输出：${name}记录、签名与时间</textarea></label><label>完成条件<textarea>${special}</textarea></label><label>异常处理<select><option>保留数据并退回上一节点</option><option>转人工处理</option></select></label><label>页面权限<select><option>办理人可填写，其他人只读</option><option>按字段配置</option></select></label></aside>`}
flowDesigner=function(){return `<div class="workflow-v2 simplified"><aside class="workflow-library"><h3>流程节点</h3><small>业务页面按使用阶段归类，可重复拖入</small>${libGroup('通用节点',general)}${libGroup('标准业务节点 · 作业前',beforeWork,'作业前')}${libGroup('标准业务节点 · 作业中',duringWork,'作业中')}</aside><main class="workflow-center"><div class="simple-flow-toolbar"><b>流程画布</b><div><button id="simpleUndo">撤销</button><button id="simpleClear">清空</button><button id="simpleAuto">自动布局</button><select id="simpleFlowState"><option>正常状态</option><option>加载状态</option><option>空状态</option><option>错误状态</option><option>无权限</option></select></div></div><div class="simple-flow-board" id="simpleFlowBoard">${board()}</div><div class="simple-flow-hint">拖动左侧节点到画布添加；气体检测可分别放在作业前和作业中，复用同一个页面。</div><div hidden><input id="nodeName"><button id="removeNode">删除</button><button id="autoLayout">自动布局</button><button id="wfValidate">校验</button><select id="wfState"><option value="normal">正常</option></select></div></main>${flowProperties()}</div>`};
function openApprovalEditor(index=-1){const current=approvalRows[index]||{name:'',role:'自定义成员',photo:'非必填'};document.querySelector('#modalBody').innerHTML=`<h2>${index<0?'新增':'编辑'}审批节点</h2><div class="approval-editor-form"><label><span><i>*</i> 审批节点</span><input id="approvalName" value="${current.name}" placeholder="请输入审批节点"></label><label><span><i>*</i> 审批人</span><select id="approvalRole">${['自定义成员','作业负责人','作业所在单位负责人','作业监护人','风险评估人','安全措施确认人','安全交底人','安全管理人员'].map(x=>`<option ${x===current.role?'selected':''}>${x}</option>`).join('')}</select></label><label><span><i>*</i> 现场照片</span><select id="approvalPhoto"><option ${current.photo==='非必填'?'selected':''}>非必填</option><option ${current.photo==='必填'?'selected':''}>必填</option></select></label></div><div class="dialog-footer"><button class="ghost" id="cancelApproval">取消</button><button class="primary" id="saveApproval">确定</button></div>`;openModalShell();document.querySelector('#cancelApproval').onclick=closeModalShell;document.querySelector('#saveApproval').onclick=()=>{const name=document.querySelector('#approvalName').value.trim();if(!name)return toast('请输入审批节点');const row={name,role:document.querySelector('#approvalRole').value,photo:document.querySelector('#approvalPhoto').value};if(index<0)approvalRows.push(row);else approvalRows[index]=row;closeModalShell();renderDesigner();toast('审批节点已保存')}}
function bindSimpleFlow(){let drag=null;const addNode=(type,stage='')=>{if(type==='开始节点'&&flowNodes.some(x=>x.type===type))return toast('流程只能有一个开始节点');if(type==='结束节点'&&flowNodes.some(x=>x.type===type))return toast('流程只能有一个结束节点');const business=standard.includes(type),end=flowNodes.findIndex(x=>x.type==='结束节点'),at=end<0?flowNodes.length:end,name=type==='开始节点'?'申请作业票':type==='审批节点'?'作业审批':type==='气体检测'?`气体检测（${stage}）`:type.replace('节点',''),item={id:`node-${Date.now()}`,name,type:business?'办理节点':type,business,baseName:business?type:'',stage:business?stage:''};flowNodes.splice(at,0,item);selectedFlowId=item.id;renderDesigner();toast(`${name}已添加`)};document.querySelectorAll('[data-simple-library]').forEach(b=>{b.onclick=()=>addNode(b.dataset.simpleLibrary,b.dataset.simpleStage);b.ondragstart=e=>{drag={kind:'new',name:b.dataset.simpleLibrary,stage:b.dataset.simpleStage};e.dataTransfer.setData('text/plain',b.dataset.simpleLibrary)}});document.querySelectorAll('[data-simple-node]').forEach(n=>{n.onclick=()=>{selectedFlowId=n.dataset.simpleNode;renderDesigner()};n.ondragstart=e=>{drag={kind:'move',id:n.dataset.simpleNode};n.classList.add('dragging');e.dataTransfer.setData('text/plain',n.dataset.simpleNode)};n.ondragend=()=>n.classList.remove('dragging');n.ondragover=e=>{e.preventDefault();n.classList.add('drag-over')};n.ondragleave=()=>n.classList.remove('drag-over');n.ondrop=e=>{e.preventDefault();e.stopPropagation();n.classList.remove('drag-over');if(!drag||drag.kind!=='move'||drag.id===n.dataset.simpleNode)return;const from=flowNodes.findIndex(x=>x.id===drag.id),to=flowNodes.findIndex(x=>x.id===n.dataset.simpleNode),item=flowNodes.splice(from,1)[0];flowNodes.splice(to,0,item);renderDesigner();toast('流程顺序已调整')}});const canvas=document.querySelector('#simpleFlowBoard');canvas.ondragover=e=>e.preventDefault();canvas.ondrop=e=>{e.preventDefault();if(drag?.kind==='new')addNode(drag.name,drag.stage)};document.querySelector('#addApprovalRow')?.addEventListener('click',()=>openApprovalEditor());document.querySelectorAll('[data-edit-approval]').forEach(x=>x.onclick=()=>openApprovalEditor(Number(x.dataset.editApproval)));document.querySelectorAll('[data-delete-approval]').forEach(x=>x.onclick=()=>{approvalRows.splice(Number(x.dataset.deleteApproval),1);renderDesigner();toast('审批节点已删除')});document.querySelector('#simpleClear').onclick=()=>{flowNodes=[];selectedFlowId='';renderDesigner()};document.querySelector('#simpleAuto').onclick=()=>toast('节点已按当前顺序自动排列');document.querySelector('#simpleUndo').onclick=()=>toast('已保留当前流程草稿');document.querySelector('#simpleFlowState').onchange=e=>{const value=e.target.value;if(value==='空状态'){flowNodes=[];selectedFlowId='';renderDesigner()}else if(value!=='正常状态')toast(`${value}仅用于原型验证`)}};
const bindBefore=bindDesigner;bindDesigner=function(){if(state.mode==='form')return bindBefore();document.querySelector('#backCenter').onclick=centerView;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;renderDesigner()});document.querySelector('#saveTemplate').onclick=()=>toast(`${state.template.name}的表单与流程已保存为草稿`);const test=document.querySelector('#testTemplate');if(test)test.style.display='none';const prev=document.querySelector('#flowPrev');if(prev)prev.onclick=renderFormBuildStep;const next=document.querySelector('#toPublish');if(next)next.onclick=renderPublishStep;bindSimpleFlow()};
renderPublishStep=function(){ensure();const valid=flowNodes.some(x=>x.type==='开始节点')&&flowNodes.some(x=>x.type==='结束节点')&&flowNodes.length>=3;title.textContent=`${state.template.name} · 测试与发布`;subtitle.textContent='检查当前模板配置并发布';app.innerHTML=`<div class="build-shell">${top(4)}<main class="draft-config-main simple-publish"><div class="validation-dashboard"><article><b>${valid?'通过':'待完善'}</b><span>流程完整性</span></article><article><b>${flowNodes.length}</b><span>流程节点</span></article><article><b>${typeof canvasControls!=='undefined'?canvasControls.length:fields.length}</b><span>表单控件</span></article></div><div class="simple-publish-grid"><section class="publish-card"><h3>模板检查</h3><p>模板名称、编码和适用作业类型已确认。</p><span class="tag published">已通过</span></section><section class="publish-card"><h3>表单检查</h3><p>申请表单已保存，必填字段和默认权限已校验。</p><span class="tag published">已通过</span></section><section class="publish-card"><h3>流程检查</h3><p>${valid?'开始、办理/审批与结束节点连接完整。':'请至少配置开始节点、一个处理或审批节点和结束节点。'}</p><span class="tag ${valid?'published':'draft'}">${valid?'已通过':'待完善'}</span></section><section class="publish-card"><h3>发布信息</h3><label>发布说明<textarea placeholder="请输入本次调整说明"></textarea></label><label>生效时间<input type="datetime-local"></label></section></div><div class="dialog-footer"><button id="publishBack">上一步</button><button class="primary" id="publishSimple" ${valid?'':'disabled'}>发布模板</button></div></main></div>`;document.querySelector('#simpleClose').onclick=centerView;document.querySelector('#simpleNext').style.display='none';document.querySelector('#publishBack').onclick=()=>{state.mode='flow';renderDesigner()};document.querySelector('#publishSimple').onclick=()=>{state.template.status='已发布';toast('模板已发布');setTimeout(centerView,700)}};
window.openTemplatePublishCheck=renderPublishStep;
document.addEventListener('click',event=>{const previous=event.target.closest('#flowPrev');if(!previous)return;event.preventDefault();event.stopImmediatePropagation();state.mode='form';renderFormBuildStep()},true);
})();
